#!/usr/bin/env python3
"""Turn design/icon/bagosynths.svg into the Android drawables it feeds.

The SVG is the source of truth; everything under app/src/main/res that this
writes carries a DO NOT EDIT header. Run it after changing the drawing:

    python tools/svg2vd.py

WHY A SCRIPT AND NOT AN EXPORT. Android Studio's vector import would do this
once, by hand, and the SVG would then drift from the XML with nothing to catch
it. A converter in the repo means the drawing has exactly one definition, and
"did someone edit the generated file" is answerable by running it again and
looking at the diff.

WHY NO PNGs. minSdk is 29, so every device that can install this supports
adaptive icons (API 26). The launcher rasterises the vector itself at whatever
density and mask it wants, which is strictly better than a ladder of PNGs
pulled from the same SVG: no density is missing, and nothing is stale.

It handles only the SVG subset the icon uses -- <path> with a solid fill --
which is deliberate. A general SVG converter would be a project; this is a tool
for one drawing, and it fails loudly on anything it was not built for.
"""
import os
import re
import sys
import xml.etree.ElementTree as ET

SVG_NS = "http://www.w3.org/2000/svg"
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SRC = os.path.join(ROOT, "design", "icon", "bagosynths.svg")
RES = os.path.join(ROOT, "app", "src", "main", "res")

HEADER = ("<!-- GENERATED by tools/svg2vd.py from design/icon/bagosynths.svg."
          " DO NOT EDIT. -->\n")

VECTOR = """<?xml version="1.0" encoding="utf-8"?>
{header}<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="108dp"
    android:height="108dp"
    android:viewportWidth="108"
    android:viewportHeight="108">
{paths}</vector>
"""

ADAPTIVE = """<?xml version="1.0" encoding="utf-8"?>
{header}<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@drawable/ic_launcher_background"/>
    <foreground android:drawable="@drawable/ic_launcher_foreground"/>
    <monochrome android:drawable="@drawable/ic_launcher_monochrome"/>
</adaptive-icon>
"""


def paths_of(group):
    """Every <path> in a group, as (d, fill, mono-role)."""
    out = []
    for el in group.findall("{%s}path" % SVG_NS):
        d = el.get("d")
        fill = el.get("fill")
        if not d or not fill:
            sys.exit("path with no d= or no fill= -- this converter needs both")
        if el.get("stroke") or el.get("opacity") or el.get("transform"):
            sys.exit("stroke/opacity/transform are outside the supported subset")
        out.append((d, fill, el.get("data-mono", "solid")))
    return out


def vector(paths, fill_type=None):
    body = ""
    for d, fill, _ in paths:
        body += '    <path\n        android:fillColor="%s"\n' % fill
        if fill_type:
            body += '        android:fillType="%s"\n' % fill_type
        body += '        android:pathData="%s"/>\n' % d
    return VECTOR.format(header=HEADER, paths=body)


def monochrome(paths):
    """One path, even-odd: `solid` shapes filled, `hole` shapes punched out.

    Themed icons are tinted a single colour, so drawing the keys on top of the
    bag would merge them into it. Punching them through the bag instead is what
    keeps the icon legible when the launcher recolours it.
    """
    d = " ".join(p for p, _, role in paths if role in ("solid", "hole"))
    return vector([(d, "#000000", "solid")], fill_type="evenOdd")


def write(rel, text):
    dest = os.path.join(RES, rel)
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    # Binary, LF: this repo is edited from Windows and a stray CRLF in a
    # generated file turns every regeneration into a whole-file diff.
    with open(dest, "wb") as f:
        f.write(text.replace("\r\n", "\n").encode("utf-8"))
    print("wrote %s" % rel)


def main():
    tree = ET.parse(SRC)
    groups = {g.get("id"): g for g in tree.getroot().findall("{%s}g" % SVG_NS)}
    for need in ("background", "foreground"):
        if need not in groups:
            sys.exit('bagosynths.svg needs a <g id="%s">' % need)

    fg = paths_of(groups["foreground"])
    write("drawable/ic_launcher_background.xml", vector(paths_of(groups["background"])))
    write("drawable/ic_launcher_foreground.xml", vector(fg))
    write("drawable/ic_launcher_monochrome.xml", monochrome(fg))
    for name in ("ic_launcher", "ic_launcher_round"):
        write("mipmap-anydpi-v26/%s.xml" % name, ADAPTIVE.format(header=HEADER))


if __name__ == "__main__":
    main()
